typedef long long ll;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> C(N);
    for (int i = 0; i < N; ++i) {
        cin >> C[i];
    }

    int M;
    cin >> M;
    vector<vector<int>> adj(N);
    vector<int> indeg(N, 0);
    for (int i = 0; i < M; ++i) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        adj[a].push_back(b);
        indeg[b]++;
    }

    // Topological order
    queue<int> q;
    for (int i = 0; i < N; ++i) {
        if (indeg[i] == 0) q.push(i);
    }
    vector<int> topo;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        topo.push_back(u);
        for (int v : adj[u]) {
            if (--indeg[v] == 0) q.push(v);
        }
    }

    // dp[i] = max calories achievable from machine i (including its own)
    vector<ll> dp(N);
    ll ans = 0;
    for (int i = N-1; i >= 0; --i) {
        int u = topo[i];
        dp[u] = C[u];
        ll best_next = 0;
        for (int v : adj[u]) {
            best_next = max(best_next, dp[v]);
        }
        dp[u] += best_next;
        ans = max(ans, dp[u]);
    }

    cout << ans << "\n";
    return 0;
}

