int main(){
    int N, T;
    cin >> N >> T;
    vector<long long> c(N+1);
    for(int i=1;i<=N;i++) cin>>c[i];

    vector<long long> uses(N+1, 0);
    // Available: machine 1 always, machine i if uses[i] < uses[i-1]
    // Use priority queue with (calorie, machine_index)
    priority_queue<pair<long long,int>> pq;
    pq.push({c[1], 1});

    long long total = 0;
    for(int t=0;t<T;t++){
        if(pq.empty()) break;
        auto [cal, idx] = pq.top();
        pq.pop();
        total += cal;
        uses[idx]++;
        // Now machine idx+1 might become available
        if(idx+1 <= N && uses[idx+1] < uses[idx]){
            // machine idx+1 was not available before (uses[idx+1] == uses[idx]-1 == uses[idx] after increment - 1)
            // Actually check if it just became available
            if(uses[idx] > uses[idx+1]){
                // It was already potentially in queue or not
                // We need to be careful not to add duplicates
                // uses[idx] just increased by 1, so if uses[idx] == uses[idx+1]+1... 
                // it just became newly available if uses[idx] was equal to uses[idx+1] before
                if(uses[idx] - 1 == uses[idx+1]){ // before increment they were equal
                    pq.push({c[idx+1], idx+1});
                }
            }
        }
        // Machine idx can still be used (always available if idx==1, or uses[idx] < uses[idx-1])
        if(idx == 1 || uses[idx] < uses[idx-1]){
            pq.push({c[idx], idx});
        }
    }

    cout << total << endl;
    return 0;
}

