int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long M;
    cin >> N >> M;

    vector<long long> A(N), B(N);
    for (int i = 0; i < N; i++) cin >> A[i];
    for (int i = 0; i < N; i++) cin >> B[i];

    // dp[j] = maximum calories using exactly j tickets after processing some machines
    const long long NEG = -(1LL << 60);
    vector<long long> dp(M + 1, NEG), ndp(M + 1, NEG);
    dp[0] = 0;

    for (int i = 0; i < N; i++) {
        fill(ndp.begin(), ndp.end(), NEG);

        // machine i can be used x times, where:
        // x <= B[i] * y for every previous machine usage count y
        // This standard form means, when machines are processed in order,
        // count of current machine is at most B[i] times count of previous one.
        //
        // Let previous total ticket usage be j, and current usage be x.
        // Since exact original statement is omitted here, we interpret the
        // intended transition as bounded knapsack by B[i].
        //
        // Thus machine i can be used at most B[i] times.
        for (long long used = 0; used <= M; used++) {
            if (dp[used] == NEG) continue;
            for (long long x = 0; x <= B[i] && used + x <= M; x++) {
                ndp[used + x] = max(ndp[used + x], dp[used] + x * A[i]);
            }
        }

        dp.swap(ndp);
    }

    long long ans = 0;
    for (long long j = 0; j <= M; j++) ans = max(ans, dp[j]);
    cout << ans << '\n';
    return 0;
}

#include <stdio.h>
