#include <limits.h>

#define MAXN 105
#define MAXM 10005
#define INF 1000000000

typedef struct {
    int to, rev;
    int cap, cost;
} Edge;

Edge edges[MAXM];
int head[MAXN], nxt[MAXM], eidx;
int dist[MAXN], prevv[MAXN], preve[MAXN];
int inq[MAXN];
int q[MAXN * MAXN], qh, qt;

void add_edge(int from, int to, int cap, int cost) {
    edges[eidx] = (Edge){to, eidx + 1, cap, cost};
    nxt[eidx] = head[from];
    head[from] = eidx++;
    edges[eidx] = (Edge){from, eidx - 1, 0, -cost};
    nxt[eidx] = head[to];
    head[to] = eidx++;
}

int min_cost_flow(int s, int t, int maxf, int N) {
    int res = 0, flow = 0;
    while (flow < maxf) {
        for (int i = 0; i < N; i++) dist[i] = INF;
        dist[s] = 0;
        qh = qt = 0;
        q[qt++] = s;
        inq[s] = 1;
        while (qh < qt) {
            int v = q[qh++];
            inq[v] = 0;
            for (int i = head[v]; i != -1; i = nxt[i]) {
                Edge &e = edges[i];
                if (e.cap > 0 && dist[e.to] > dist[v] + e.cost) {
                    dist[e.to] = dist[v] + e.cost;
                    prevv[e.to] = v;
                    preve[e.to] = i;
                    if (!inq[e.to]) {
                        q[qt++] = e.to;
                        inq[e.to] = 1;
                    }
                }
            }
        }
        if (dist[t] == INF) break;
        int d = maxf - flow;
        for (int v = t; v != s; v = prevv[v])
            if (edges[preve[v]].cap < d) d = edges[preve[v]].cap;
        flow += d;
        res += d * dist[t];
        for (int v = t; v != s; v = prevv[v]) {
            edges[preve[v]].cap -= d;
            edges[edges[preve[v]].rev].cap += d;
        }
    }
    return flow < maxf ? -1 : res;
}

int main() {
    int N, M, K;
    scanf("%d %d %d", &N, &M, &K);

    int cal[MAXN];
    for (int i = 1; i <= N; i++) scanf("%d", &cal[i]);

    memset(head, -1, sizeof(head));
    eidx = 0;

    int S = 0, T = N + 1;
    // source to each machine: capacity K (total tickets), cost = -cal (since we want max, we minimize negative)
    for (int i = 1; i <= N; i++) {
        add_edge(S, i, K, -cal[i]);
    }
    // each machine to sink: capacity K
    for (int i = 1; i <= N; i++) {
        add_edge(i, T, K, 0);
    }

    // constraints: machine a can be used at most b times more than machine c
    // means: use[a] - use[c] <= b
    // Equivalent to: use[a] - use[c] <= b
    // In flow: a->c with capacity b, cost 0
    for (int i = 0; i < M; i++) {
        int a, b, c;
        scanf("%d %d %d", &a, &b, &c);
        add_edge(a, c, b, 0);
    }

    int ans = -min_cost_flow(S, T, K, N + 2); // negative of min cost = max calorie
    printf("%d\n", ans);
    return 0;
}

