int main() {
    int N, T;
    scanf("%d %d", &N, &T);

    int c[N+1];
    for (int i = 1; i <= N; i++) scanf("%d", &c[i]);

    // prefix sums S[k] = c[1]+...+c[k]
    long long S[N+1];
    S[0] = 0;
    for (int i = 1; i <= N; i++) S[i] = S[i-1] + c[i];

    // unbounded knapsack: dp[t] = max calories with t tickets
    long long dp[T+1];
    memset(dp, 0, sizeof(dp));

    for (int t = 1; t <= T; t++) {
        for (int k = 1; k <= N && k <= t; k++) {
            long long val = dp[t - k] + S[k];
            if (val > dp[t]) dp[t] = val;
        }
    }

    printf("%lld\n", dp[T]);
    return 0;
}

