typedef long long ll;

static int cmp_ll_desc(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return 1;
    if (x > y) return -1;
    return 0;
}

int main(void) {
    int N;
    ll M;
    if (scanf("%d %lld", &N, &M) != 2) return 0;

    ll *A = (ll *)malloc(sizeof(ll) * N);
    if (!A) return 0;

    for (int i = 0; i < N; i++) scanf("%lld", &A[i]);

    qsort(A, N, sizeof(ll), cmp_ll_desc);

    /*
      Interpretation:
      If machine i is used xi times, rules are:
        x1 >= x2 >= ... >= xN >= 0
      and total tickets used:
        x1 + x2 + ... + xN <= M

      Maximize sum(A[i] * xi).

      Since A is sorted descending, for any fixed total T <= M,
      the best nonincreasing integer sequence is obtained by making it
      as "front-loaded" as possible, i.e. choose some k and distribute
      T among first k machines so that:
        x1 >= x2 >= ... >= xk
      This is equivalent to selecting a partition of T, and by majorization
      the optimal for descending weights is:
        x_i = floor((T + k - i) / k) for i=1..k
      for some k, when all first k are used as evenly as needed.

      More directly, for each k (1..N), if only first k machines are used,
      the maximum total uses respecting nonincreasing order and using exactly T
      among them is achieved by assigning:
        q = T / k, r = T % k
        first r machines: q+1
        next k-r machines: q
      because this is the unique nonincreasing sequence with minimal spread.

      Since all A[i] >=? not specified, but using up to M tickets means we can
      choose T from 0..M. For positive calories, use all M. Standard tasks of
      this type assume positive values, so we use all M.
    */

    ll ans = 0;

    for (int k = 1; k <= N; k++) {
        ll q = M / k;
        ll r = M % k;

        ll cur = 0;
        for (int i = 0; i < k; i++) {
            ll times = q + (i < r ? 1 : 0);
            cur += A[i] * times;
        }
        if (cur > ans) ans = cur;
    }

    printf("%lld\n", ans);

    free(A);
    return 0;
}

